export default [{"id":"2030","jozz":"15","page":"282","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"3","line_end":"5","aya_no":"1","aya_text":"سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ","aya_text_emlaey":"سبحان الذي أسرى بعبده ليلا من المسجد الحرام إلى المسجد الأقصى الذي باركنا حوله لنريه من آياتنا إنه هو السميع البصير","aya_tafseer":"[1] يمجِّد الله نفسه ويعظم شأنه، لقدرته على ما لا يقدر عليه أحد سواه، لا إله غيره، ولا رب سواه، فهو الذي أسرى بعبده محمد -صلى الله عليه وسلم- زمناً من الليل بجسده وروحه، يقظة لا مناماً، من المسجد الحرام ﺑ«مكة» إلى المسجد الأقصى ﺑ«بيت المقدس» الذي بارك الله حوله في الزروع والثمار وغير ذلك، وجعله محلّاً لكثير من الأنبياء؛ ليشاهد عجائب قدرة الله وأدلَّة وحدانيته. إن الله سبحانه وتعالى هو السميع لجميع الأصوات، البصير بكل مُبْصَر، فيعطي كُلّاً ما يستحقه في الدنيا والآخرة."},{"id":"2031","jozz":"15","page":"282","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"5","line_end":"6","aya_no":"2","aya_text":"وَءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَٰٓءِيلَ أَلَّا تَتَّخِذُواْ مِن دُونِي وَكِيلٗا","aya_text_emlaey":"وآتينا موسى الكتاب وجعلناه هدى لبني إسرائيل ألا تتخذوا من دوني ‎وكيلا","aya_tafseer":"[2] وكما كرَّم الله محمداً -صلى الله عليه وسلم- بالإسراء، كَرَّم موسى عليه السلام بإعطائه التوراة، وجعلها بياناً للحق وإرشاداً لبني إسرائيل، متضمنة نهيهم عن اتخاذ غير الله تعالى ولياً أو معبوداً يفوضون إليه أمورهم."},{"id":"2032","jozz":"15","page":"282","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"7","line_end":"7","aya_no":"3","aya_text":"ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدٗا شَكُورٗا","aya_text_emlaey":"ذرية من حملنا مع نوح إنه كان عبدا شكورا","aya_tafseer":"[3] يا سلالة الذين أنجيناهم وحَمَلْناهم مع نوح في السفينة لا تشركوا بالله في عبادته، وكونوا شاكرين لنعمه، مقتدين بنوح عليه السلام؛ إنه كان عبداً شكوراً لله بقلبه ولسانه وجوارحه."},{"id":"2033","jozz":"15","page":"282","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"8","line_end":"9","aya_no":"4","aya_text":"وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ فِي ٱلۡكِتَٰبِ لَتُفۡسِدُنَّ فِي ٱلۡأَرۡضِ مَرَّتَيۡنِ وَلَتَعۡلُنَّ عُلُوّٗا كَبِيرٗا","aya_text_emlaey":"وقضينا إلى بني إسرائيل في الكتاب لتفسدن في الأرض مرتين ولتعلن علوا كبيرا","aya_tafseer":"[4] وأخبرنا بني إسرائيل في التوراة التي أُنزلت عليهم بأنه لابد أن يقع منهم إفساد مرتين في «بيت المقدس» وما والاه بالظلم، وقَتْل الأنبياء، والتكبر والطغيان والعدوان."},{"id":"2034","jozz":"15","page":"282","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"9","line_end":"11","aya_no":"5","aya_text":"فَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَيۡكُمۡ عِبَادٗا لَّنَآ أُوْلِي بَأۡسٖ شَدِيدٖ فَجَاسُواْ خِلَٰلَ ٱلدِّيَارِۚ وَكَانَ وَعۡدٗا مَّفۡعُولٗا","aya_text_emlaey":"فإذا جاء وعد أولاهما بعثنا عليكم عبادا لنا أولي بأس شديد فجاسوا خلال الديار وكان وعدا مفعولا","aya_tafseer":"[5] فإذا وقع منكم الإفساد الأول سَلَّطْنا عليكم عباداً لنا ذوي شجاعة وقوة شديدة، يغلبونكم ويقتلونكم ويشردونكم، فطافوا بين دياركم مفسدين، وكان ذلك وعداً لا بدَّ مِن وقوعه؛ لوجود سببه منكم."},{"id":"2035","jozz":"15","page":"282","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"11","line_end":"12","aya_no":"6","aya_text":"ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَيۡهِمۡ وَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلٖ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا","aya_text_emlaey":"ثم رددنا لكم الكرة عليهم وأمددناكم بأموال وبنين وجعلناكم أكثر نفيرا","aya_tafseer":"[6] ثم رَدَدْنا لكم -يا بني إسرائيل- الغلبة والظهور على أعدائكم الذين سُلِّطوا عليكم، وأكثرنا أرزاقكم وأولادكم، وقَوَّيناكم وجعلناكم أكثر عدداً من عدوكم؛ وذلك بسبب إحسانكم وخضوعكم لله."},{"id":"2036","jozz":"15","page":"282","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"13","line_end":"15","aya_no":"7","aya_text":"إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمۡ وَلِيَدۡخُلُواْ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٖ وَلِيُتَبِّرُواْ مَا عَلَوۡاْ تَتۡبِيرًا","aya_text_emlaey":"إن أحسنتم أحسنتم لأنفسكم وإن أسأتم فلها فإذا جاء وعد الآخرة ليسوءوا وجوهكم وليدخلوا المسجد كما دخلوه أول مرة وليتبروا ما علوا تتبيرا","aya_tafseer":"[7] إن أحسنتم أفعالكم وأقوالكم فقد أحسنتم لأنفسكم؛ لأن ثواب ذلك عائد إليكم، وإن أسأتم فعقاب ذلك عائد عليكم، فإذا حان موعد الإفساد الثاني سَلَّطْنا عليكم أعداءكم مرة أخرى؛ ليذلوكم ويغلبوكم، فتظهر آثار الإهانة والمذلة على وجوهكم، وليدخلوا عليكم «بيت المقدس» فيخرِّبوه، كما خرَّبوه أول مرة، وليدمروا كل ما وقع تحت أيديهم تدميراً كاملاً."},{"id":"2037","jozz":"15","page":"283","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"2","aya_no":"8","aya_text":"عَسَىٰ رَبُّكُمۡ أَن يَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ حَصِيرًا","aya_text_emlaey":"عسى ربكم أن يرحمكم وإن عدتم عدنا وجعلنا جهنم للكافرين حصيرا","aya_tafseer":"[8] عسى ربكم -يا بني إسرائيل- أن يرحمكم بعد انتقامه إن تبتم وأصلحتم، وإن عدتم إلى الإفساد والظلم عُدْنا إلى عقابكم ومذلَّتكم. وجعلنا جهنم لكم وللكافرين عامة سجناً لا خروج منه أبداً. وفي هذه الآية وما قبلها، تحذير لهذه الأمة من العمل بالمعاصي؛ لئلا يصيبها مثل ما أصاب بني إسرائيل، فسنن الله واحدة لا تبدَّل ولا تغيَّر."},{"id":"2038","jozz":"15","page":"283","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"2","line_end":"3","aya_no":"9","aya_text":"إِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَهۡدِي لِلَّتِي هِيَ أَقۡوَمُ وَيُبَشِّرُ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرٗا كَبِيرٗا","aya_text_emlaey":"إن هذا القرآن يهدي للتي هي أقوم ويبشر المؤمنين الذين يعملون الصالحات أن لهم أجرا كبيرا","aya_tafseer":"[9] إن هذا القرآن الذي أنزلناه على عبدنا محمد -صلى الله عليه وسلم- يرشد الناس إلى أحسن الطرق، وهي ملة الإسلام، ويبشر المؤمنين الذين يعملون بما أمرهم الله به، وينتهون عمَّا نهاهم عنه، بأن لهم ثواباً عظيماً ."},{"id":"2039","jozz":"15","page":"283","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"4","line_end":"4","aya_no":"10","aya_text":"وَأَنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا","aya_text_emlaey":"وأن الذين لا يؤمنون بالآخرة أعتدنا لهم عذابا أليما","aya_tafseer":"[10] وأن الذين لا يصدقون بالدار الآخرة وما فيها من الجزاء أعددنا لهم عذاباً موجعاً في النار."},{"id":"2040","jozz":"15","page":"283","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"5","line_end":"5","aya_no":"11","aya_text":"وَيَدۡعُ ٱلۡإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلۡخَيۡرِۖ وَكَانَ ٱلۡإِنسَٰنُ عَجُولٗا","aya_text_emlaey":"ويدع الإنسان بالشر دعاءه بالخير وكان الإنسان عجولا","aya_tafseer":"[11] ويدعو الإنسان أحياناً على نفسه أو ولده أو ماله بالشر، وذلك عند الغضب، مثل ما يدعو بالخير، وهذا من جهل الإنسان وعجلته، ومن رحمة الله به أنه يستجيب له في دعائه بالخير دون الشر؛ لأنه يعلم منه عدم القصد إلى إرادة ذلك، وكان الإنسان بطبعه عجولاً."},{"id":"2041","jozz":"15","page":"283","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"6","line_end":"8","aya_no":"12","aya_text":"وَجَعَلۡنَا ٱلَّيۡلَ وَٱلنَّهَارَ ءَايَتَيۡنِۖ فَمَحَوۡنَآ ءَايَةَ ٱلَّيۡلِ وَجَعَلۡنَآ ءَايَةَ ٱلنَّهَارِ مُبۡصِرَةٗ لِّتَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ وَكُلَّ شَيۡءٖ فَصَّلۡنَٰهُ تَفۡصِيلٗا","aya_text_emlaey":"وجعلنا الليل والنهار آيتين فمحونا آية الليل وجعلنا آية النهار مبصرة لتبتغوا فضلا من ربكم ولتعلموا عدد السنين والحساب وكل شيء فصلناه تفصيلا","aya_tafseer":"[12] وجعلنا الليل والنهار علامتين دالَّتين على وحدانيتنا وقدرتنا، فمَحَوْنا علامة الليل -وهي القمر- وجعلنا علامة النهار -وهي الشمس- مضيئة؛ ليبصر الإنسان في ضوء النهار كيف يتصرف في شؤون معاشه، ويخلد في الليل إلى السكن والراحة، وليعلم الناس -مِن تعاقب الليل والنهار- عدد السنين وحساب الأشهر والأيام، فيرتبون عليها ما يشاؤون من مصالحهم، وكل شيء بيَّناه تبييناً كافياً."},{"id":"2042","jozz":"15","page":"283","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"8","line_end":"10","aya_no":"13","aya_text":"وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ فِي عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ كِتَٰبٗا يَلۡقَىٰهُ مَنشُورًا","aya_text_emlaey":"وكل إنسان ألزمناه طائره في عنقه ونخرج له يوم القيامة كتابا يلقاه منشورا","aya_tafseer":"[13] وكل إنسان يجعل الله ما عمله مِن خير أو شر ملازماً له، فلا يحاسَب بعمل غيره، ولا يحاسَب غيره بعمله، ويخرج الله له يوم القيامة كتاباً قد سُجِّلت فيه أعماله يراه مفتوحاً."},{"id":"2043","jozz":"15","page":"283","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"10","line_end":"10","aya_no":"14","aya_text":"ٱقۡرَأۡ كِتَٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡيَوۡمَ عَلَيۡكَ حَسِيبٗا","aya_text_emlaey":"اقرأ كتابك كفى بنفسك اليوم عليك حسيبا","aya_tafseer":"[14] يقال له: اقرأ كتاب أعمالك، فيقرأ، وإن لم يكن يعرف القراءة في الدنيا، تكفيك نفسك اليوم محصية عليك عملك، فتعرف ما عليها من جزاء. وهذا من أعظم العدل والإنصاف أن يقال للعبد: حاسِبْ نفسك، كفى بها حسيباً عليك."},{"id":"2044","jozz":"15","page":"283","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"11","line_end":"13","aya_no":"15","aya_text":"مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولٗا","aya_text_emlaey":"من اهتدى فإنما يهتدي لنفسه ومن ضل فإنما يضل عليها ولا تزر وازرة وزر أخرى وما كنا معذبين حتى نبعث رسولا","aya_tafseer":"[15] من اهتدى فاتبع طريق الحق فإنما يعود ثواب ذلك عليه وحده، ومن حاد واتبع طريق الباطل فإنما يعود عقاب ذلك عليه وحده، ولا تحمل نفس مذنبة إثم نفس مذنبة أخرى. ولا يعذب الله أحداً إلا بعد إقامة الحجة عليه بإرسال الرسل وإنزال الكتب."},{"id":"2045","jozz":"15","page":"283","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"13","line_end":"14","aya_no":"16","aya_text":"وَإِذَآ أَرَدۡنَآ أَن نُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَٰهَا تَدۡمِيرٗا","aya_text_emlaey":"وإذا أردنا أن نهلك قرية أمرنا مترفيها ففسقوا فيها فحق عليها القول فدمرناها تدميرا","aya_tafseer":"[16] وإذا أردنا إهلاك أهل قرية لظلمهم أَمَرْنا مترفيهم بطاعة الله وتوحيده وتصديق رسله، وغيرهم تبع لهم، فعصَوا أمر ربهم وكذَّبوا رسله، فحقَّ عليهم القول بالعذاب الذي لا مردَّ له، فاستأصلناهم بالهلاك التام."},{"id":"2046","jozz":"15","page":"283","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"14","line_end":"15","aya_no":"17","aya_text":"وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحٖۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرَۢا بَصِيرٗا","aya_text_emlaey":"وكم أهلكنا من القرون من بعد نوح وكفى بربك بذنوب عباده خبيرا بصيرا","aya_tafseer":"[17] وكثيراً أهلكنا من الأمم المكذبة رسلها مِن بعد نبي الله نوح. وكفى بربك -أيها الرسول- أنه عالم بجميع أعمال عباده، لا تخفى عليه خافية."},{"id":"2047","jozz":"15","page":"284","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"2","aya_no":"18","aya_text":"مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ يَصۡلَىٰهَا مَذۡمُومٗا مَّدۡحُورٗا","aya_text_emlaey":"من كان يريد العاجلة عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصلاها مذموما مدحورا","aya_tafseer":"[18] من كان طلبه الدنيا العاجلة، وسعى لها وحدها، ولم يصدِّق بالآخرة، ولم يعمل لها، عجَّل الله له فيها ما يشاؤه الله ويريده مما كتبه له في اللوح المحفوظ، ثم يجعل الله له في الآخرة جهنم، يدخلها ملوماً مطروداً من رحمته عز وجل؛ وذلك بسبب إرادته الدنيا وسعيه لها دون الآخرة."},{"id":"2048","jozz":"15","page":"284","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"2","line_end":"4","aya_no":"19","aya_text":"وَمَنۡ أَرَادَ ٱلۡأٓخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِنٞ فَأُوْلَٰٓئِكَ كَانَ سَعۡيُهُم مَّشۡكُورٗا","aya_text_emlaey":"ومن أراد الآخرة وسعى لها سعيها وهو مؤمن فأولئك كان سعيهم مشكورا","aya_tafseer":"[19] ومَن قصد بعمله الصالح ثواب الدار الآخرة الباقية، وسعى لها بطاعة الله تعالى، وهو مؤمن بالله وثوابه وعظيم جزائه، فأولئك كان عملهم مقبولاً مُدَّخراً لهم عند ربهم، وسيثابون عليه."},{"id":"2049","jozz":"15","page":"284","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"4","line_end":"5","aya_no":"20","aya_text":"كُلّٗا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنۡ عَطَآءِ رَبِّكَۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحۡظُورًا","aya_text_emlaey":"كلا نمد هؤلاء وهؤلاء من عطاء ربك وما كان عطاء ربك محظورا","aya_tafseer":"[20] كل فريق من العاملين للدنيا الفانية، والعاملين للآخرة الباقية نزيده مِن رزقنا، فنرزق المؤمنين والكافرين في الدنيا؛ فإن الرزق مِن عطاء ربك تفضلاً منه، وما كان عطاء ربك ممنوعاً من أحد مؤمناً كان أم كافراً."},{"id":"2050","jozz":"15","page":"284","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"5","line_end":"7","aya_no":"21","aya_text":"ٱنظُرۡ كَيۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۚ وَلَلۡأٓخِرَةُ أَكۡبَرُ دَرَجَٰتٖ وَأَكۡبَرُ تَفۡضِيلٗا","aya_text_emlaey":"انظر كيف فضلنا بعضهم على بعض وللآخرة أكبر درجات وأكبر تفضيلا","aya_tafseer":"[21] تأمل -أيها الرسول- في كيفية تفضيل الله بعض الناس على بعض في الدنيا في الرزق والعمل، ولَلآخرة أكبرُ درجات للمؤمنين وأكبر تفضيلاً."},{"id":"2051","jozz":"15","page":"284","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"7","line_end":"8","aya_no":"22","aya_text":"لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومٗا مَّخۡذُولٗا","aya_text_emlaey":"لا تجعل مع الله إلها آخر فتقعد مذموما مخذولا","aya_tafseer":"[22] لا تجعل -أيها الإنسان- مع الله شريكاً له في عبادته، فتبوء بالمذمة والخِذْلان."},{"id":"2052","jozz":"15","page":"284","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"8","line_end":"10","aya_no":"23","aya_text":"۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا","aya_text_emlaey":"وقضى ربك ألا تعبدوا إلا إياه وبالوالدين إحسانا إما يبلغن عندك الكبر أحدهما أو كلاهما فلا تقل لهما أف ولا تنهرهما وقل لهما قولا كريما","aya_tafseer":"[23] وأَمَر ربك -أيها الإنسان- وألزم وأوجب أن يفرد سبحانه وتعالى وحده بالعبادة، وأمر بالإحسان إلى الأب والأم، وبخاصة حالةُ الشيخوخة إذا كانا في رعايتك، فلا تضجر ولا تستثقل شيئاً تراه من أحدهما أو منهما، ولا تُسْمِعهما قولاً سيئاً، حتى ولا التأفيف الذي هو أدنى مراتب القول السيئ، ولا يصدر منك إليهما فعل قبيح، ولكن ارفق بهما، وقل لهما -دائماً- قولاً ليناً لطيفاً."},{"id":"2053","jozz":"15","page":"284","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"10","line_end":"12","aya_no":"24","aya_text":"وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا","aya_text_emlaey":"واخفض لهما جناح الذل من الرحمة وقل رب ارحمهما كما ربياني صغيرا","aya_tafseer":"[24] وكُنْ لأمك وأبيك ذليلاً متواضعاً رحمة بهما، واطلب من ربك أن يرحمهما برحمته الواسعة أحياءً وأمواتاً، كما صبرا على تربيتك طفلاً ضعيف الحول والقوة."},{"id":"2054","jozz":"15","page":"284","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"12","line_end":"13","aya_no":"25","aya_text":"رَّبُّكُمۡ أَعۡلَمُ بِمَا فِي نُفُوسِكُمۡۚ إِن تَكُونُواْ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلۡأَوَّٰبِينَ غَفُورٗا","aya_text_emlaey":"ربكم أعلم بما في نفوسكم إن تكونوا صالحين فإنه كان للأوابين غفورا","aya_tafseer":"[25] ربكم -أيها الناس- أعلم بما في ضمائركم مِن خير وشر. إن تكن إرادتكم ومقاصدكم مرضاة الله وما يقربكم إليه، فإنه كان -سبحانه- للراجعين إليه في جميع الأوقات غفوراً، فمَن عَلِمَ الله أنه ليس في قلبه إلا الإنابة إليه ومحبته، فإنه يعفو عنه، ويغفر له ما يعرض من صغائر الذنوب؛ مما هو من مقتضى الطبائع البشرية."},{"id":"2055","jozz":"15","page":"284","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"13","line_end":"14","aya_no":"26","aya_text":"وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا","aya_text_emlaey":"وآت ذا القربى حقه والمسكين وابن السبيل ولا تبذر تبذيرا","aya_tafseer":"[26] وأحسِنْ إلى كل مَن له صلة قرابة بك، وأعطه حقه من الإحسان والبر، وأعط المسكين الذي لا يَمْلك ما يكفيه ويسدُّ حاجته، والمسافر المنقطع عن أهله وماله، ولا تنفق مالك في غير طاعة الله، أو على وجه الإسراف والتبذير."},{"id":"2056","jozz":"15","page":"284","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"14","line_end":"15","aya_no":"27","aya_text":"إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورٗا","aya_text_emlaey":"إن المبذرين كانوا إخوان الشياطين وكان الشيطان لربه كفورا","aya_tafseer":"[27] إن المسرفين والمنفقين أموالهم في معاصي الله هم أشباه الشياطين في الشر والفساد والمعصية، وكان الشيطان كثيرَ الكفران شديدَ الجحود لنعمة ربه."},{"id":"2057","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"2","aya_no":"28","aya_text":"وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةٖ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلٗا مَّيۡسُورٗا","aya_text_emlaey":"وإما تعرضن عنهم ابتغاء رحمة من ربك ترجوها فقل لهم قولا ميسورا","aya_tafseer":"[28] وإن أعرضت عن إعطاء هؤلاء الذين أُمِرْت بإعطائهم؛ لعدم وجود ما تعطيهم منه طلباً لرزق تنتظره مِن عند ربك، فقل لهم قولاً ليِّناً لطيفاً، كالدعاء لهم بالغنى وسعة الرزق، وعِدْهم بأن الله إذا أيسر من فضله رزقاً أنك تعطيهم منه."},{"id":"2058","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"2","line_end":"3","aya_no":"29","aya_text":"وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا","aya_text_emlaey":"ولا تجعل يدك مغلولة إلى عنقك ولا تبسطها كل البسط فتقعد ملوما محسورا","aya_tafseer":"[29] ولا تمسك يدك عن الإنفاق في سبيل الخير، مضيِّقاً على نفسك وأهلك والمحتاجين، ولا تسرف في الإنفاق، فتعطي فوق طاقتك، فتقعد ملوماً يلومك الناس ويذمونك، نادماً على تبذيرك وضياع مالك."},{"id":"2059","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"3","line_end":"4","aya_no":"30","aya_text":"إِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا","aya_text_emlaey":"إن ربك يبسط الرزق لمن يشاء ويقدر إنه كان بعباده خبيرا بصيرا","aya_tafseer":"[30] إن ربك يوسِّع الرزق على بعض الناس، ويضيِّقه على بعضهم، وَفْق علمه وحكمته سبحانه وتعالى. إنه هو المطَّلِع على خفايا عباده، لا يغيب عن علمه شيء من أحوالهم."},{"id":"2060","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"4","line_end":"6","aya_no":"31","aya_text":"وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٖۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـٔٗا كَبِيرٗا","aya_text_emlaey":"ولا تقتلوا أولادكم خشية إملاق نحن نرزقهم وإياكم إن قتلهم كان خطئا كبيرا","aya_tafseer":"[31] وإذا علمتم أن الرزق بيد الله سبحانه فلا تقتلوا -أيها الناس- أولادكم خوفاً من الفقر؛ فإنه -سبحانه- هو الرزاق لعباده، يرزق الأبناء كما يرزق الآباء، إنَّ قَتْلَ الأولاد ذنب عظيم."},{"id":"2061","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"6","line_end":"7","aya_no":"32","aya_text":"وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَسَآءَ سَبِيلٗا","aya_text_emlaey":"ولا تقربوا الزنا إنه كان فاحشة وساء سبيلا","aya_tafseer":"[32] ولا تقربوا الزنى ودواعيه؛ كي لا تقعوا فيه، إنه كان فعلاً بالغ القبح، وبئس الطريق طريقه."},{"id":"2062","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"7","line_end":"9","aya_no":"33","aya_text":"وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومٗا فَقَدۡ جَعَلۡنَا لِوَلِيِّهِۦ سُلۡطَٰنٗا فَلَا يُسۡرِف فِّي ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورٗا","aya_text_emlaey":"ولا تقتلوا النفس التي حرم الله إلا بالحق ومن قتل مظلوما فقد جعلنا لوليه سلطانا فلا يسرف في القتل إنه كان منصورا","aya_tafseer":"[33] ولا تقتلوا النفس التي حرم الله قَتْلها إلا بالحق الشرعي كالقصاص أو رجم الزاني المحصن أو قتل المرتد. ومَن قُتِل بغير حق شرعي فقد جعلنا لولي أمره مِن وارث أو حاكم حجة في طلب قَتْل قاتله أو الدية، ولا يصح لولي أمر المقتول أن يجاوز حدَّ الله في القصاص كأن يقتل بالواحد اثنين أو جماعة، أو يُمَثِّل بالقاتل، إن الله معين وليَّ المقتول على القاتل حتى يتمكن مِن قَتْله قصاصاً."},{"id":"2063","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"9","line_end":"11","aya_no":"34","aya_text":"وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولٗا","aya_text_emlaey":"ولا تقربوا مال اليتيم إلا بالتي هي أحسن حتى يبلغ أشده وأوفوا بالعهد إن العهد كان مسئولا","aya_tafseer":"[34] ولا تتصرَّفوا في أموال الأطفال الذين مات آباؤهم وهم دون سنِّ البلوغ، وصاروا في كفالتكم، إلا بالطريقة التي هي أحسن لهم، وهي التثمير والتنمية، حتى يبلغ الطفل اليتيم سنَّ البلوغ، وحسن التصرف في المال، وأتموا الوفاء بكل عهد التزمتم به. إن العهد يسأل الله عنه صاحبه يوم القيامة، فيثيبه إذا أتمه ووفَّاه، ويعاقبه إذا خان فيه."},{"id":"2064","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"11","line_end":"12","aya_no":"35","aya_text":"وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلٗا","aya_text_emlaey":"وأوفوا الكيل إذا كلتم وزنوا بالقسطاس المستقيم ذلك خير وأحسن تأويلا","aya_tafseer":"[35] وأتموا الكيل، ولا تنقصوه إذا كِلْتم لغيركم، وزِنوا بالميزان السوي، إن العدل في الكيل والوزن خير لكم في الدنيا، وأحسن عاقبة عند الله في الآخرة."},{"id":"2065","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"12","line_end":"13","aya_no":"36","aya_text":"وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا","aya_text_emlaey":"ولا تقف ما ليس لك به علم إن السمع والبصر والفؤاد كل أولئك كان عنه مسئولا","aya_tafseer":"[36] ولا تتبع -أيها الإنسان- ما لا تعلم، بل تأكَّد وتثبَّت. إن الإنسان مسؤول عما استعمَل فيه سمعه وبصره وفؤاده، فإذا استعمَلها في الخير نال الثواب، وإذا استعملها في الشر نال العقاب."},{"id":"2066","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"14","line_end":"15","aya_no":"37","aya_text":"وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولٗا","aya_text_emlaey":"ولا تمش في الأرض مرحا إنك لن تخرق الأرض ولن تبلغ الجبال طولا","aya_tafseer":"[37] ولا تمش في الأرض مختالاً متكبراً؛ فإنك لن تَخْرِق الأرض بمشيك عليها بهذه الصفة، ولن تبلغ الجبال طولاً بخيلائك وفخرك وكبرك."},{"id":"2067","jozz":"15","page":"285","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"15","line_end":"15","aya_no":"38","aya_text":"كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهٗا","aya_text_emlaey":"كل ذلك كان سيئه عند ربك مكروها","aya_tafseer":"[38] جميع ما تقدَّم ذِكْرُه من أوامر ونواهٍ، يكره الله سيِّئَه، ولا يرضاه لعباده."},{"id":"2068","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"2","aya_no":"39","aya_text":"ذَٰلِكَ مِمَّآ أَوۡحَىٰٓ إِلَيۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلۡقَىٰ فِي جَهَنَّمَ مَلُومٗا مَّدۡحُورًا","aya_text_emlaey":"ذلك مما أوحى إليك ربك من الحكمة ولا تجعل مع الله إلها آخر فتلقى في جهنم ملوما مدحورا","aya_tafseer":"[39] ذلك الذي بينَّاه ووضَّحناه مِن هذه الأحكام الجليلة، من الأمر بمحاسن الأعمال، والنهي عن أراذل الأخلاق مما أوحيناه إليك أيها النبي. ولا تجعل -أيها الإنسان- مع الله تعالى شريكاً له في عبادته، فتُقْذف في نار جهنم تلومك نفسك والناس، وتكون مطروداً مبعداً من كل خير."},{"id":"2069","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"2","line_end":"3","aya_no":"40","aya_text":"أَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِينَ وَٱتَّخَذَ مِنَ ٱلۡمَلَٰٓئِكَةِ إِنَٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِيمٗا","aya_text_emlaey":"أفأصفاكم ربكم بالبنين واتخذ من الملائكة إناثا إنكم لتقولون قولا عظيما","aya_tafseer":"[40] أفخصَّكم ربكم -أيها المشركون- بإعطائكم البنين، واتخذ لنفسه الملائكة بنات؟ إن قولكم هذا بالغ القبح والبشاعة، لا يليق بالله سبحانه وتعالى."},{"id":"2070","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"4","line_end":"4","aya_no":"41","aya_text":"وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِيَذَّكَّرُواْ وَمَا يَزِيدُهُمۡ إِلَّا نُفُورٗا","aya_text_emlaey":"ولقد صرفنا في هذا القرآن ليذكروا وما يزيدهم إلا نفورا","aya_tafseer":"[41] ولقد وضَّحْنا ونوَّعْنا في هذا القرآن الأحكام والأمثال والمواعظ؛ ليتعظ الناس ويتدبروا ما ينفعهم فيأخذوه، وما يضرهم فيدَعوه، وما يزيد البيان والتوضيح الظالمين إلا تباعداً عن الحق، وغفلة عن النظر والاعتبار."},{"id":"2071","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"5","line_end":"5","aya_no":"42","aya_text":"قُل لَّوۡ كَانَ مَعَهُۥٓ ءَالِهَةٞ كَمَا يَقُولُونَ إِذٗا لَّٱبۡتَغَوۡاْ إِلَىٰ ذِي ٱلۡعَرۡشِ سَبِيلٗا","aya_text_emlaey":"قل لو كان معه آلهة كما يقولون إذا لابتغوا إلى ذي العرش سبيلا","aya_tafseer":"[42] قل -أيها الرسول- للمشركين: لو أن مع الله آلهة أخرى، إذاً لطلبَتْ تلك الآلهة طريقاً إلى مغالبة الله ذي العرش العظيم."},{"id":"2072","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"6","line_end":"6","aya_no":"43","aya_text":"سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوّٗا كَبِيرٗا","aya_text_emlaey":"سبحانه وتعالى عما يقولون علوا كبيرا","aya_tafseer":"[43] تنزَّه الله وتقدَّس عَمَّا يقوله المشركون وتعالى علواً كبيراً."},{"id":"2073","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"6","line_end":"8","aya_no":"44","aya_text":"تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا","aya_text_emlaey":"تسبح له السموات السبع والأرض ومن فيهن وإن من شيء إلا يسبح بحمده ولكن لا تفقهون تسبيحهم إنه كان حليما غفورا","aya_tafseer":"[44] تُسَبِّح له -سبحانه- السموات السبع والأرضون، ومَن فيهن مِن جميع المخلوقات، وكل شيء في هذا الوجود ينزه الله تعالى تنزيهاً مقروناً بالثناء والحمد له سبحانه، ولكن لا تدركون -أيها الناس- ذلك. إنه سبحانه كان حليماً بعباده لا يعاجل مَن عصاه بالعقوبة، غفوراً لهم."},{"id":"2074","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"8","line_end":"10","aya_no":"45","aya_text":"وَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ حِجَابٗا مَّسۡتُورٗا","aya_text_emlaey":"وإذا قرأت القرآن جعلنا بينك وبين الذين لا يؤمنون بالآخرة حجابا مستورا","aya_tafseer":"[45] وإذا قرأت القرآن فسمعه هؤلاء المشركون، جعلنا بينك وبين الذين لا يؤمنون بالآخرة حجاباً ساتراً يحجب عقولهم عن فَهْمِ القرآن؛ عقاباً لهم على كفرهم وإنكارهم."},{"id":"2075","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"10","line_end":"11","aya_no":"46","aya_text":"وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورٗا","aya_text_emlaey":"وجعلنا على قلوبهم أكنة أن يفقهوه وفي آذانهم وقرا وإذا ذكرت ربك في القرآن وحده ولوا على أدبارهم نفورا","aya_tafseer":"[46] وجعلنا على قلوب المشركين أغطية؛ لئلا يفهموا القرآن، وجعلنا في آذانهم صمماً؛ لئلا يسمعوه، وإذا ذَكَرْتَ ربك في القرآن داعياً لتوحيده ناهياً عن الشرك به رجعوا على أعقابهم نافرين مِن قولك؛ استكباراً واستعظاماً من أن يوحِّدوا الله تعالى في عبادته."},{"id":"2076","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"12","line_end":"13","aya_no":"47","aya_text":"نَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِهِۦٓ إِذۡ يَسۡتَمِعُونَ إِلَيۡكَ وَإِذۡ هُمۡ نَجۡوَىٰٓ إِذۡ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا","aya_text_emlaey":"نحن أعلم بما يستمعون به إذ يستمعون إليك وإذ هم نجوى إذ يقول الظالمون إن تتبعون إلا رجلا مسحورا","aya_tafseer":"[47] نحن أعلم بالذي يستمع به رؤساء قريش، إذ يستمعون إليك ومقاصدهم سيئة، فليس استماعهم لأجل الاسترشاد وقَبول الحق، ونعلم تَناجيهم حين يقولون: ما تتبعون إلا رجلاً أصابه السحر فاختلط عقله."},{"id":"2077","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"13","line_end":"14","aya_no":"48","aya_text":"ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَالَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلٗا","aya_text_emlaey":"انظر كيف ضربوا لك الأمثال فضلوا فلا يستطيعون سبيلا","aya_tafseer":"[48] تفكر -أيها الرسول- متعجباً من قولهم: إن محمداً ساحر شاعر مجنون ! فجاروا وانحرفوا، ولم يهتدوا إلى طريق الحق والصواب."},{"id":"2078","jozz":"15","page":"286","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"15","line_end":"15","aya_no":"49","aya_text":"وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدٗا","aya_text_emlaey":"وقالوا أئذا كنا عظاما ورفاتا أئنا لمبعوثون خلقا جديدا","aya_tafseer":"[49] وقال المشركون منكرين أن يُخْلَقوا خَلْقاً جديداً بعد أن تبلى عظامهم، وتصير فُتاتاً: أئِنا لمبعوثون يوم القيامة بعثاً جديداً؟"},{"id":"2079","jozz":"15","page":"287","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"1","aya_no":"50","aya_text":"۞ قُلۡ كُونُواْ حِجَارَةً أَوۡ حَدِيدًا","aya_text_emlaey":"قل كونوا حجارة أو حديدا","aya_tafseer":"[50] قل لهم -أيها الرسول- على جهة التعجيز: كونوا حجارة أو حديداً في الشدة والقوة، إن قَدَرْتم على ذلك."},{"id":"2080","jozz":"15","page":"287","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"4","aya_no":"51","aya_text":"أَوۡ خَلۡقٗا مِّمَّا يَكۡبُرُ فِي صُدُورِكُمۡۚ فَسَيَقُولُونَ مَن يُعِيدُنَاۖ قُلِ ٱلَّذِي فَطَرَكُمۡ أَوَّلَ مَرَّةٖۚ فَسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ وَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن يَكُونَ قَرِيبٗا","aya_text_emlaey":"أو خلقا مما يكبر في صدوركم فسيقولون من يعيدنا قل الذي فطركم أول مرة فسينغضون إليك رءوسهم ويقولون متى هو قل عسى أن يكون قريبا","aya_tafseer":"[51] أو كونوا خلقاً يَعْظُم ويُسْتَبْعَد في عقولكم قبوله، فسيقولون -منكرين-: مَن يردُّنا إلى الحياة بعد الموت؟ قل لهم: يعيدكم ويرجعكم الله الذي أنشأكم من العدم أول مرة، وعند سماعهم هذا الرد فسيَهُزُّون رؤوسهم ساخرين متعجبين ويقولون -مستبعدين-: متى يقع هذا البعث؟ قل: وما يدريكم أن هذا البعث الذي تنكرونه وتستبعدونه ربما كان قريب الوقوع؟"},{"id":"2081","jozz":"15","page":"287","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"4","line_end":"5","aya_no":"52","aya_text":"يَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗا","aya_text_emlaey":"يوم يدعوكم فتستجيبون بحمده وتظنون إن لبثتم إلا قليلا","aya_tafseer":"[52] يوم يناديكم خالقكم للخروج من قبوركم، فتستجيبون لأمر الله، وتنقادون له، وله الحمد على كل حال، وتظنون -لهول يوم القيامة- أنكم ما أقمتم في الدنيا إلا زمناً قليلاً؛ لطول لبثكم في الآخرة."},{"id":"2082","jozz":"15","page":"287","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"5","line_end":"7","aya_no":"53","aya_text":"وَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوّٗا مُّبِينٗا","aya_text_emlaey":"وقل لعبادي يقولوا التي هي أحسن إن الشيطان ينـزغ بينهم إن الشيطان كان للإنسان عدوا مبينا","aya_tafseer":"[53] وقل لعبادي المؤمنين يقولوا في تخاطبهم وتحاورهم الكلام الحسن الطيب؛ فإنهم إن لم يفعلوا ذلك ألقى الشيطان بينهم العداوة والفساد والخصام. إن الشيطان كان للإنسان عدوّاً ظاهر العداوة."},{"id":"2083","jozz":"15","page":"287","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"7","line_end":"8","aya_no":"54","aya_text":"رَّبُّكُمۡ أَعۡلَمُ بِكُمۡۖ إِن يَشَأۡ يَرۡحَمۡكُمۡ أَوۡ إِن يَشَأۡ يُعَذِّبۡكُمۡۚ وَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ وَكِيلٗا","aya_text_emlaey":"ربكم أعلم بكم إن يشأ يرحمكم أو إن يشأ يعذبكم وما أرسلناك عليهم وكيلا","aya_tafseer":"[54] ربكم أعلم بكم -أيها الناس- إن يشأ يرحمكم فيوفقكم للإيمان، أو إن يشأ يمتكم على الكفر فيعذبكم، وما أرسلناك -أيها الرسول- عليهم وكيلاً، تدبِّر أمرهم وتجازيهم على أفعالهم، وإنما مهمتك تبليغ ما أُرْسلتَ به، وبيان الصراط المستقيم."},{"id":"2084","jozz":"15","page":"287","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"8","line_end":"10","aya_no":"55","aya_text":"وَرَبُّكَ أَعۡلَمُ بِمَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعۡضٖۖ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا","aya_text_emlaey":"وربك أعلم بمن في السموات والأرض ولقد فضلنا بعض النبيين على بعض وآتينا داود زبورا","aya_tafseer":"[55] وربك -أيها الرسول- أعلم بمَن في السموات والأرض. ولقد فَضَّلْنا بعض النبيين على بعض بالفضائل وكثرة الأتباع وإنزال الكتب، وأعطينا داود عليه السَّلام الزبور."},{"id":"2085","jozz":"15","page":"287","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"10","line_end":"11","aya_no":"56","aya_text":"قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا يَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِيلًا","aya_text_emlaey":"قل ادعوا الذين زعمتم من دونه فلا يملكون كشف الضر عنكم ولا تحويلا","aya_tafseer":"[56] قل -أيها الرسول- لمشركي قومك: إن هذه المعبودات التي تنادونها لكشف الضرِّ عنكم لا تملك ذلك، ولا تقدر على تحويله عنكم إلى غيركم، ولا تقدر على تحويله من حال إلى حال، فالقادر على ذلك هو الله وحده. وهذه الآية عامة في كل ما يُدْعى من دون الله، ميتاً كان أو غائباً، من الأنبياء والصالحين وغيرهم، بلفظ الاستغاثة أو الدعاء أو غيرهما، فلا معبود بحق إلا الله."},{"id":"2086","jozz":"15","page":"287","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"11","line_end":"14","aya_no":"57","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ يَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحۡذُورٗا","aya_text_emlaey":"أولئك الذين يدعون يبتغون إلى ربهم الوسيلة أيهم أقرب ويرجون رحمته ويخافون عذابه إن عذاب ربك كان محذورا","aya_tafseer":"[57] أولئك الذين يدعوهم المشركون، من الأنبياء والصالحين والملائكة مع الله، يتنافسون في القرب من ربهم بما يقدرون عليه من الأعمال الصالحة، ويأمُلون رحمته ويخافون عذابه، إن عذاب ربك هو ما ينبغي أن يحذره العباد، ويخافوا منه."},{"id":"2087","jozz":"15","page":"287","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"14","line_end":"15","aya_no":"58","aya_text":"وَإِن مِّن قَرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ يَوۡمِ ٱلۡقِيَٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابٗا شَدِيدٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا","aya_text_emlaey":"وإن من قرية إلا نحن مهلكوها قبل يوم القيامة أو معذبوها عذابا شديدا كان ذلك في الكتاب مسطورا","aya_tafseer":"[58] ويتوعَّد الله الكفار بأنه ما مِن قريةٍ كافرة مكذبة للرسل إلا وسيُنزل بها عقابه بالهلاك في الدنيا قبل يوم القيامة، أو بالعذاب الشديد لأهلها، كتاب كتبه الله وقضاء أبرمه لابد مِن وقوعه، وهو مسطور في اللوح المحفوظ."},{"id":"2088","jozz":"15","page":"288","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"3","aya_no":"59","aya_text":"وَمَا مَنَعَنَآ أَن نُّرۡسِلَ بِٱلۡأٓيَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَۚ وَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةٗ فَظَلَمُواْ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡأٓيَٰتِ إِلَّا تَخۡوِيفٗا","aya_text_emlaey":"وما منعنا أن نرسل بالآيات إلا أن كذب بها الأولون وآتينا ثمود الناقة مبصرة فظلموا بها وما نرسل بالآيات إلا تخويفا","aya_tafseer":"[59] وما منعَنا من إنزال المعجزات التي سألها المشركون إلا تكذيب مَن سبقهم من الأمم، فقد أجابهم الله إلى ما طلبوا فكذَّبوا وهلكوا. وأعطينا ثمود -وهم قوم صالح- معجزة واضحة وهي الناقة، فكفروا بها فأهلكناهم. وما إرسالنا الرسلَ بالآيات والعبر والمعجزات التي جعلناها على أيديهم إلا تخويف للعباد؛ ليعتبروا ويتذكروا."},{"id":"2089","jozz":"15","page":"288","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"3","line_end":"5","aya_no":"60","aya_text":"وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةٗ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا","aya_text_emlaey":"وإذ قلنا لك إن ربك أحاط بالناس وما جعلنا الرؤيا التي أريناك إلا فتنة للناس والشجرة الملعونة في القرآن ونخوفهم فما يزيدهم إلا طغيانا كبيرا","aya_tafseer":"[60] واذكر -أيها الرسول- حين قلنا لك: إن ربك أحاط بالناس علماً وقدرة. وما جعلنا الرؤيا التي أريناكها عِياناً ليلة الإسراء والمعراج من عجائب المخلوقات، إلا اختباراً للناس؛ ليتميز كافرهم من مؤمنهم، وما جعلنا شجرة الزقوم الملعونةَ التي ذكرت في القرآن إلا ابتلاء للناس. ونخوِّف المشركين بأنواع العذاب والآيات، ولا يزيدهم التخويف إلا تمادياً في الكفر والضلال."},{"id":"2090","jozz":"15","page":"288","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"6","line_end":"7","aya_no":"61","aya_text":"وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ قَالَ ءَأَسۡجُدُ لِمَنۡ خَلَقۡتَ طِينٗا","aya_text_emlaey":"وإذ قلنا للملائكة اسجدوا لآدم فسجدوا إلا إبليس قال أأسجد لمن خلقت طينا","aya_tafseer":"[61] واذكر قولنا للملائكة: اسجدوا لآدم تحية وتكريماً، فسجدوا جميعاً إلا إبليس، استكبر وامتنع عن السجود قائلاً على سبيل الإنكار والاستكبار: أأسجد لهذا الضعيف، المخلوق من الطين؟"},{"id":"2091","jozz":"15","page":"288","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"7","line_end":"9","aya_no":"62","aya_text":"قَالَ أَرَءَيۡتَكَ هَٰذَا ٱلَّذِي كَرَّمۡتَ عَلَيَّ لَئِنۡ أَخَّرۡتَنِ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَأَحۡتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلٗا","aya_text_emlaey":"قال أرأيتك هذا الذي كرمت علي لئن أخرتني إلى يوم القيامة لأحتنكن ذريته إلا قليلا","aya_tafseer":"[62] وقال إبليس جراءة على الله وكفراً به: أرأيت هذا المخلوق الذي ميزته عليَّ؟ لئن أبقيتني حيّاً إلى يوم القيامة لأستولينَّ على ذريته بالإغواء والإفساد، إلا المخلصين منهم في الإيمان، وهم قليل."},{"id":"2092","jozz":"15","page":"288","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"9","line_end":"10","aya_no":"63","aya_text":"قَالَ ٱذۡهَبۡ فَمَن تَبِعَكَ مِنۡهُمۡ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمۡ جَزَآءٗ مَّوۡفُورٗا","aya_text_emlaey":"قال اذهب فمن تبعك منهم فإن جهنم جزاؤكم جزاء موفورا","aya_tafseer":"[63] قال الله تعالى مهدداً إبليس وأتباعَه: اذهب فمَن تبعك مِن ذرية آدم فأطاعك، فإن عقابك وعقابهم وافر في نار جهنم."},{"id":"2093","jozz":"15","page":"288","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"10","line_end":"13","aya_no":"64","aya_text":"وَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَيۡهِم بِخَيۡلِكَ وَرَجِلِكَ وَشَارِكۡهُمۡ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِ وَعِدۡهُمۡۚ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا","aya_text_emlaey":"واستفزز من استطعت منهم بصوتك وأجلب عليهم بخيلك ورجلك وشاركهم في الأموال والأولاد وعدهم وما يعدهم الشيطان إلا غرورا","aya_tafseer":"[64] واستَخْفِف كل مَن تستطيع استخفافه منهم بدعوتك إياه إلى معصيتي، واجمع عليهم كل ما تقدر عليه مِن جنودك من كل راكب وراجل، واجعل لنفسك شِرْكة في أموالهم بأن يكسِبوها من الحرام وينفقوها فيه، وشِرْكة في الأولاد بتزيين الزنى والمعاصي، ومخالفة أوامر الله حتى يكثر الفجور والفساد، وعِدْ أتباعك مِن ذرية آدم الوعود الكاذبة، فكل وعود الشيطان باطلة وغرور."},{"id":"2094","jozz":"15","page":"288","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"13","line_end":"14","aya_no":"65","aya_text":"إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٞۚ وَكَفَىٰ بِرَبِّكَ وَكِيلٗا","aya_text_emlaey":"إن عبادي ليس لك عليهم سلطان وكفى بربك وكيلا","aya_tafseer":"[65] إن عبادي المؤمنين المخلصين الذين أطاعوني ليس لك قدرة على إغوائهم، وكفى بربك -أيها النبي- عاصماً وحافظاً للمؤمنين مِن كيد الشيطان وغروره."},{"id":"2095","jozz":"15","page":"288","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"14","line_end":"15","aya_no":"66","aya_text":"رَّبُّكُمُ ٱلَّذِي يُزۡجِي لَكُمُ ٱلۡفُلۡكَ فِي ٱلۡبَحۡرِ لِتَبۡتَغُواْ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ كَانَ بِكُمۡ رَحِيمٗا","aya_text_emlaey":"ربكم الذي يزجي لكم الفلك في البحر لتبتغوا من فضله إنه كان بكم رحيما","aya_tafseer":"[66] ربكم -أيها الناس- هو الذي يُسَيِّر لكم السفن في البحر؛ لتطلبوا رزق الله في أسفاركم وتجاراتكم. إن الله سبحانه كان رحيماً بعباده."},{"id":"2096","jozz":"15","page":"289","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"2","aya_no":"67","aya_text":"وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِي ٱلۡبَحۡرِ ضَلَّ مَن تَدۡعُونَ إِلَّآ إِيَّاهُۖ فَلَمَّا نَجَّىٰكُمۡ إِلَى ٱلۡبَرِّ أَعۡرَضۡتُمۡۚ وَكَانَ ٱلۡإِنسَٰنُ كَفُورًا","aya_text_emlaey":"وإذا مسكم الضر في البحر ضل من تدعون إلا إياه فلما نجاكم إلى البر أعرضتم وكان الإنسان كفورا","aya_tafseer":"[67] وإذا أصابتكم شدة في البحر حتى أشرفتم على الغرق والهلاك، غاب عن عقولكم الذين تعبدونهم من الآلهة، وتذكَّرتم الله القدير وحده؛ ليغيثكم وينقذكم، فأخلصتم له في طلب العون والإغاثة، فأغاثكم ونجَّاكم، فلمَّا نجاكم إلى البر أعرضتم عن الإيمان والإخلاص والعمل الصالح، وهذا من جهل الإنسان وكفره. وكان الإنسان جحوداً لنعم الله عزَّ وجل."},{"id":"2097","jozz":"15","page":"289","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"2","line_end":"4","aya_no":"68","aya_text":"أَفَأَمِنتُمۡ أَن يَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗا ثُمَّ لَا تَجِدُواْ لَكُمۡ وَكِيلًا","aya_text_emlaey":"أفأمنتم أن يخسف بكم جانب البر أو يرسل عليكم حاصبا ثم لا تجدوا لكم وكيلا","aya_tafseer":"[68] أغَفَلْتم -أيها الناس- عن عذاب الله، فأمنتم أن تنهار بكم الأرض خسفاً، أو يُمْطركم الله بحجارة من السماء فتقتلكم، ثم لا تجدوا أحداً يحفظكم مِن عذابه؟"},{"id":"2098","jozz":"15","page":"289","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"4","line_end":"6","aya_no":"69","aya_text":"أَمۡ أَمِنتُمۡ أَن يُعِيدَكُمۡ فِيهِ تَارَةً أُخۡرَىٰ فَيُرۡسِلَ عَلَيۡكُمۡ قَاصِفٗا مِّنَ ٱلرِّيحِ فَيُغۡرِقَكُم بِمَا كَفَرۡتُمۡ ثُمَّ لَا تَجِدُواْ لَكُمۡ عَلَيۡنَا بِهِۦ تَبِيعٗا","aya_text_emlaey":"أم أمنتم أن يعيدكم فيه تارة أخرى فيرسل عليكم قاصفا من الريح فيغرقكم بما كفرتم ثم لا تجدوا لكم علينا به تبيعا","aya_tafseer":"[69] أم أمنتم -أيها الناس- ربكم، وقد كفرتم به أن يعيدكم في البحر مرة أخرى، فيرسل عليكم ريحاً شديدة، تكسِّر كل ما أتت عليه، فيغرقكم بسبب كفركم، ثم لا تجدوا لكم علينا أي تبعة ومطالبة؛ فإن الله لم يظلمكم مثقال ذرة؟"},{"id":"2099","jozz":"15","page":"289","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"6","line_end":"8","aya_no":"70","aya_text":"۞ وَلَقَدۡ كَرَّمۡنَا بَنِيٓ ءَادَمَ وَحَمَلۡنَٰهُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا","aya_text_emlaey":"ولقد كرمنا بني آدم وحملناهم في البر والبحر ورزقناهم من الطيبات وفضلناهم على كثير ممن خلقنا تفضيلا","aya_tafseer":"[70] ولقد كرَّمنا ذرية آدم بالعقل وإرسال الرسل، وسَخَّرنا لهم جميع ما في الكون، وسَخَّرنا لهم الدواب في البر والسفن في البحر لحملهم، ورزقناهم من طيبات المطاعم والمشارب، وفضَّلناهم على كثير من المخلوقات تفضيلاً عظيماً."},{"id":"2100","jozz":"15","page":"289","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"8","line_end":"10","aya_no":"71","aya_text":"يَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۭ بِإِمَٰمِهِمۡۖ فَمَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَٰٓئِكَ يَقۡرَءُونَ كِتَٰبَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلٗا","aya_text_emlaey":"يوم ندعوا كل أناس بإمامهم فمن أوتي كتابه بيمينه فأولئك يقرءون كتابهم ولا يظلمون فتيلا","aya_tafseer":"[71] اذكر -أيها الرسول- يوم البعث مبشراً ومخوفاً، حين يدعو الله عز وجل كل جماعة من الناس مع إمامهم الذي كانوا يقتدون به في الدنيا، فمن كان منهم صالحاً، وأُعطي كتاب أعماله بيمينه، فهؤلاء يقرؤون كتاب حسناتهم فرحين مستبشرين، ولا يُنْقَصون من ثواب أعمالهم الصالحة شيئاً، وإن كان مقدارَ الخيط الذي يكون في شَقِّ النَّواة."},{"id":"2101","jozz":"15","page":"289","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"10","line_end":"11","aya_no":"72","aya_text":"وَمَن كَانَ فِي هَٰذِهِۦٓ أَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلٗا","aya_text_emlaey":"ومن كان في هذه أعمى فهو في الآخرة أعمى وأضل سبيلا","aya_tafseer":"[72] ومن كان في هذه الدنيا أعمى القلب عن دلائل قدرة الله فلم يؤمن بما جاء به الرسول محمد -صلى الله عليه وسلم- فهو في يوم القيامة أشدُّ عمى عن سلوك طريق الجنة، وأضل طريقاً عن الهداية والرشاد."},{"id":"2102","jozz":"15","page":"289","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"11","line_end":"13","aya_no":"73","aya_text":"وَإِن كَادُواْ لَيَفۡتِنُونَكَ عَنِ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ لِتَفۡتَرِيَ عَلَيۡنَا غَيۡرَهُۥۖ وَإِذٗا لَّٱتَّخَذُوكَ خَلِيلٗا","aya_text_emlaey":"وإن كادوا ليفتنونك عن الذي أوحينا إليك لتفتري علينا غيره وإذا لاتخذوك خليلا","aya_tafseer":"[73] ولقد قارب المشركون أن يصرفوك -أيها الرسول- عن القرآن الذي أنزله الله إليك؛ لتختلق علينا غير ما أوحينا إليك، ولو فعلت ما أرادوه لاتخذوك حبيباً خالصاً."},{"id":"2103","jozz":"15","page":"289","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"13","line_end":"14","aya_no":"74","aya_text":"وَلَوۡلَآ أَن ثَبَّتۡنَٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـٔٗا قَلِيلًا","aya_text_emlaey":"ولولا أن ثبتناك لقد كدت تركن إليهم شيئا قليلا","aya_tafseer":"[74] ولولا أن ثبَّتناك على الحق، وعصمناك عن موافقتهم، لَقاربْتَ أن تميل إليهم شيئاً من الميل فيما اقترحوه عليك؛ لقوة خداعهم وشدة احتيالهم، ولرغبتك في هدايتهم."},{"id":"2104","jozz":"15","page":"289","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"14","line_end":"15","aya_no":"75","aya_text":"إِذٗا لَّأَذَقۡنَٰكَ ضِعۡفَ ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيۡنَا نَصِيرٗا","aya_text_emlaey":"إذا لأذقناك ضعف الحياة وضعف الممات ثم لا تجد لك علينا نصيرا","aya_tafseer":"[75] ولو رَكَنت -أيها الرسول- إلى هؤلاء المشركين ركوناً قليلاً فيما سألوك، إذاً لأذقناك مِثْلَي عذاب الحياة في الدنيا ومثْلَي عذاب الممات في الآخرة؛ وذلك لتمام نعمة الله عليك وكمال معرفتك بربِّك، ثم لا تجد أحداً ينصرك ويدفع عنك عذابنا."},{"id":"2105","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"2","aya_no":"76","aya_text":"وَإِن كَادُواْ لَيَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَاۖ وَإِذٗا لَّا يَلۡبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلٗا","aya_text_emlaey":"وإن كادوا ليستفزونك من الأرض ليخرجوك منها وإذا لا يلبثون خلافك إلا قليلا","aya_tafseer":"[76] ولقد قارب الكفار أن يخرجوك من «مكة» بإزعاجهم إيَّاك، ولو أخرجوك منها لم يمكثوا فيها بعدك إلا زمناً قليلاً، حتى تحلَّ بهم العقوبة العاجلة."},{"id":"2106","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"2","line_end":"3","aya_no":"77","aya_text":"سُنَّةَ مَن قَدۡ أَرۡسَلۡنَا قَبۡلَكَ مِن رُّسُلِنَاۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحۡوِيلًا","aya_text_emlaey":"سنة من قد أرسلنا قبلك من رسلنا ولا تجد لسنتنا تحويلا","aya_tafseer":"[77] تلك سنة الله تعالى في إهلاك الأمة التي تُخرج رسولها مِن بينها، ولن تجد -أيها الرسول- لسنتنا تغييراً، فلا خلف في وعدنا."},{"id":"2107","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"3","line_end":"5","aya_no":"78","aya_text":"أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّيۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودٗا","aya_text_emlaey":"أقم الصلاة لدلوك الشمس إلى غسق الليل وقرآن الفجر إن قرآن الفجر كان مشهودا","aya_tafseer":"[78] أقم الصلاة تامة مِن وقت زوال الشمس عند الظهيرة إلى وقت ظلمة الليل، ويدخل في هذا صلاة الظهر والعصر والمغرب والعشاء، وأقم صلاة الفجر، وأَطِلْ القراءة فيها؛ إن صلاة الفجر تحضرها ملائكة الليل وملائكة النهار."},{"id":"2108","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"5","line_end":"6","aya_no":"79","aya_text":"وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا","aya_text_emlaey":"ومن الليل فتهجد به نافلة لك عسى أن يبعثك ربك مقاما محمودا","aya_tafseer":"[79] وقم -أيها النبي- مِن نومك بعض الليل، فاقرأ القرآن في صلاة الليل؛ لتكون صلاة الليل زيادة لك في علو القدر ورفع الدرجات، عسى أن يبعثك الله شافعاً للناس يوم القيامة؛ ليرحمهم الله مما يكونون فيه، وتقوم مقاماً يحمدك فيه الأولون والآخرون."},{"id":"2109","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"7","line_end":"8","aya_no":"80","aya_text":"وَقُل رَّبِّ أَدۡخِلۡنِي مُدۡخَلَ صِدۡقٖ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقٖ وَٱجۡعَل لِّي مِن لَّدُنكَ سُلۡطَٰنٗا نَّصِيرٗا","aya_text_emlaey":"وقل رب أدخلني مدخل صدق وأخرجني مخرج صدق واجعل لي من لدنك سلطانا نصيرا","aya_tafseer":"[80] وقل: ربِّ أدخلني فيما هو خير لي مدخل صدق، وأخرجني مما هو شر لي مخرج صدق، واجعل لي مِن لدنك حجة ثابتة، تنصرني بها على جميع مَن خالفني."},{"id":"2110","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"8","line_end":"9","aya_no":"81","aya_text":"وَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا","aya_text_emlaey":"وقل جاء الحق وزهق الباطل إن الباطل كان زهوقا","aya_tafseer":"[81] وقل -أيها الرسول- للمشركين: جاء الإسلام وذهب الشرك، إن الباطل لا بقاء له ولا ثبات، والحق هو الثابت الباقي الذي لا يزول."},{"id":"2111","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"9","line_end":"10","aya_no":"82","aya_text":"وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارٗا","aya_text_emlaey":"وننـزل من القرآن ما هو شفاء ورحمة للمؤمنين ولا يزيد الظالمين إلا خسارا","aya_tafseer":"[82] وننزل من آيات القرآن العظيم ما يشفي القلوب مِنَ الأمراض، كالشك والنفاق والجهالة، وما يشفي الأبدان برُقْيتها به، وما يكون سبباً للفوز برحمة الله بما فيه من الإيمان، ولا يزيد هذا القرآن الكفار عند سماعه إلا كفراً وضلالاً؛ لتكذيبهم به وعدم إيمانهم."},{"id":"2112","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"11","line_end":"12","aya_no":"83","aya_text":"وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسٗا","aya_text_emlaey":"وإذا أنعمنا على الإنسان أعرض ونأى بجانبه وإذا مسه الشر كان يئوسا","aya_tafseer":"[83] وإذا أنعمنا على الإنسان من حيث هو بمال وعافية ونحوهما، تولَّى وتباعد عن طاعة ربه، وإذا أصابته شدة مِن فقر أو مرض كان قنوطاً؛ لأنه لا يثق بفضل الله تعالى، إلا من عصم الله في حالتي سرَّائه وضرَّائه."},{"id":"2113","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"12","line_end":"13","aya_no":"84","aya_text":"قُلۡ كُلّٞ يَعۡمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمۡ أَعۡلَمُ بِمَنۡ هُوَ أَهۡدَىٰ سَبِيلٗا","aya_text_emlaey":"قل كل يعمل على شاكلته فربكم أعلم بمن هو أهدى سبيلا","aya_tafseer":"[84] قل -أيها الرسول- للناس: كل واحد منكم يعمل على ما يليق به من الأحوال، فربكم أعلم بمن هو أهدى طريقاً إلى الحق."},{"id":"2114","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"13","line_end":"14","aya_no":"85","aya_text":"وَيَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي وَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلٗا","aya_text_emlaey":"ويسألونك عن الروح قل الروح من أمر ربي وما أوتيتم من العلم إلا قليلا","aya_tafseer":"[85] ويسألك الكفار عن حقيقة الروح تعنتاً، فأجبهم بأن حقيقة الروح وأحوالها من الأمور التي استأثر الله بعلمها، وما أُعطيتم أنتم وجميع الناس من العلم إلا شيئاً قليلاً."},{"id":"2115","jozz":"15","page":"290","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"14","line_end":"15","aya_no":"86","aya_text":"وَلَئِن شِئۡنَا لَنَذۡهَبَنَّ بِٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيۡنَا وَكِيلًا","aya_text_emlaey":"ولئن شئنا لنذهبن بالذي أوحينا إليك ثم لا تجد لك به علينا وكيلا","aya_tafseer":"[86] ولئن شئنا مَحْوَ القرآن من قلبك لَقدَرْنا على ذلك، ثم لا تجد لنفسك ناصراً يمنعنا من فعل ذلك، أو يرد عليك القرآن."},{"id":"2116","jozz":"15","page":"291","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"1","aya_no":"87","aya_text":"إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَيۡكَ كَبِيرٗا","aya_text_emlaey":"إلا رحمة من ربك إن فضله كان عليك كبيرا","aya_tafseer":"[87] لكنَّ الله رحمك، فأثبت ذلك في قلبك، إن فضله كان عليك عظيماً؛ فقد أعطاك هذا القرآن العظيم، والمقام المحمود، وغير ذلك مما لم يؤته أحداً من العالمين."},{"id":"2117","jozz":"15","page":"291","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"3","aya_no":"88","aya_text":"قُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا","aya_text_emlaey":"قل لئن اجتمعت الإنس والجن على أن يأتوا بمثل هذا القرآن لا يأتون بمثله ولو كان بعضهم لبعض ظهيرا","aya_tafseer":"[88] قل: لو اتفقت الإنس والجن على محاولة الإتيان بمثل هذا القرآن المعجز لا يستطيعون الإتيان بمثل بلاغته ومعانيه وأحكامه، ولو تعاونوا وتظاهروا على ذلك."},{"id":"2118","jozz":"15","page":"291","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"4","line_end":"5","aya_no":"89","aya_text":"وَلَقَدۡ صَرَّفۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورٗا","aya_text_emlaey":"ولقد صرفنا للناس في هذا القرآن من كل مثل فأبى أكثر الناس إلا كفورا","aya_tafseer":"[89] ولقد بيَّنَّا ونَوَّعنا للناس في هذا القرآن من كل مثل ينبغي الاعتبار به؛ احتجاجاً بذلك عليهم؛ ليتبعوه ويعملوا به، فأبى أكثر الناس إلا جحوداً للحق وإنكاراً لحجج الله وأدلته."},{"id":"2119","jozz":"15","page":"291","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"5","line_end":"6","aya_no":"90","aya_text":"وَقَالُواْ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا","aya_text_emlaey":"وقالوا لن نؤمن لك حتى تفجر لنا من الأرض ينبوعا","aya_tafseer":"[90] ولما أعجز القرآن المشركين وغلبهم أخذوا يطلبون معجزات وَفْق أهوائهم فقالوا: لن نصدقك -يا محمد- ونعمل بما تقول حتى تفجر لنا من أرض «مكة» عيناً جارية."},{"id":"2120","jozz":"15","page":"291","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"6","line_end":"7","aya_no":"91","aya_text":"أَوۡ تَكُونَ لَكَ جَنَّةٞ مِّن نَّخِيلٖ وَعِنَبٖ فَتُفَجِّرَ ٱلۡأَنۡهَٰرَ خِلَٰلَهَا تَفۡجِيرًا","aya_text_emlaey":"أو تكون لك جنة من نخيل وعنب فتفجر الأنهار خلالها تفجيرا","aya_tafseer":"[91] أو تكون لك حديقة فيها أنواع النخيل والأعناب، وتجعل الأنهار تجري في وسطها بغزارة."},{"id":"2121","jozz":"15","page":"291","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"7","line_end":"9","aya_no":"92","aya_text":"أَوۡ تُسۡقِطَ ٱلسَّمَآءَ كَمَا زَعَمۡتَ عَلَيۡنَا كِسَفًا أَوۡ تَأۡتِيَ بِٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ قَبِيلًا","aya_text_emlaey":"أو تسقط السماء كما زعمت علينا كسفا أو تأتي بالله والملائكة قبيلا","aya_tafseer":"[92] أو تسقط السماء علينا قطعاً كما زَعَمْتَ، أو تأتي لنا بالله وملائكته، فنشاهدهم مقابلة وعِياناً."},{"id":"2122","jozz":"15","page":"291","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"9","line_end":"11","aya_no":"93","aya_text":"أَوۡ يَكُونَ لَكَ بَيۡتٞ مِّن زُخۡرُفٍ أَوۡ تَرۡقَىٰ فِي ٱلسَّمَآءِ وَلَن نُّؤۡمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيۡنَا كِتَٰبٗا نَّقۡرَؤُهُۥۗ قُلۡ سُبۡحَانَ رَبِّي هَلۡ كُنتُ إِلَّا بَشَرٗا رَّسُولٗا","aya_text_emlaey":"أو يكون لك بيت من زخرف أو ترقى في السماء ولن نؤمن لرقيك حتى تنـزل علينا كتابا نقرؤه قل سبحان ربي هل كنت إلا بشرا رسولا","aya_tafseer":"[93] أو يكون لك بيت من ذهب، أو تصعد في درج إلى السماء، ولن نصدِّقك في صعودك حتى تعود، ومعك كتاب من الله منشور نقرأ فيه أنك رسول الله حقّاً. قل -أيها الرسول- متعجباً مِن تعنُّت هؤلاء الكفار: سبحان ربي! هل أنا إلا عبد من عباده مبلِّغ رسالته؟ فكيف أقدر على فعل ما تطلبون؟"},{"id":"2123","jozz":"15","page":"291","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"11","line_end":"13","aya_no":"94","aya_text":"وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰٓ إِلَّآ أَن قَالُوٓاْ أَبَعَثَ ٱللَّهُ بَشَرٗا رَّسُولٗا","aya_text_emlaey":"وما منع الناس أن يؤمنوا إذ جاءهم الهدى إلا أن قالوا أبعث الله بشرا رسولا","aya_tafseer":"[94] وما منع الكفارَ من الإيمان بالله ورسوله وطاعتهما، حين جاءهم البيان الكافي من عند الله، إلا قولهم جهلاً وإنكاراً: أبعث الله رسولاً من جنس البشر؟"},{"id":"2124","jozz":"15","page":"291","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"13","line_end":"14","aya_no":"95","aya_text":"قُل لَّوۡ كَانَ فِي ٱلۡأَرۡضِ مَلَٰٓئِكَةٞ يَمۡشُونَ مُطۡمَئِنِّينَ لَنَزَّلۡنَا عَلَيۡهِم مِّنَ ٱلسَّمَآءِ مَلَكٗا رَّسُولٗا","aya_text_emlaey":"قل لو كان في الأرض ملائكة يمشون مطمئنين لنـزلنا عليهم من السماء ملكا رسولا","aya_tafseer":"[95] قل -أيها الرسول- ردّاً على المشركين إنكارهم أن يكون الرسول من البشر: لو كان في الأرض ملائكة يمشون عليها، ساكنين فيها، لأرسلنا إليهم رسولاً من جنسهم، ولكنَّ أهل الأرض بشر، فالرسول إليهم ينبغي أن يكون مِن جنسهم؛ ليمكنهم مخاطبته وفَهْم كلامه."},{"id":"2125","jozz":"15","page":"291","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"14","line_end":"15","aya_no":"96","aya_text":"قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا","aya_text_emlaey":"قل كفى بالله شهيدا بيني وبينكم إنه كان بعباده خبيرا بصيرا","aya_tafseer":"[96] قل لهم: كفى بالله شهيداً بيني وبينكم على صِدْقي وحقيقة نبوَّتي. إنه سبحانه خبير بأحوال عباده، بصير بأعمالهم، وسيجازيهم عليها."},{"id":"2126","jozz":"15","page":"292","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"3","aya_no":"97","aya_text":"وَمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِيَآءَ مِن دُونِهِۦۖ وَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرٗا","aya_text_emlaey":"ومن يهد الله فهو المهتد ومن يضلل فلن تجد لهم أولياء من دونه ونحشرهم يوم القيامة على وجوههم عميا وبكما وصما مأواهم جهنم كلما خبت زدناهم سعيرا","aya_tafseer":"[97] ومن يهده الله فهو المهتدي إلى الحق، ومن يضلله فيخذلْه ويَكِلْه إلى نفسه فلا هادي له من دون الله، وهؤلاء الضُّلَّال يبعثهم الله يوم القيامة، ويحشرهم على وجوههم، وهم لا يرون ولا ينطقون ولا يسمعون، مصيرهم إلى نار جهنم الملتهبة، كلما سكن لهيبها، وخمدت نارها، زدناهم ناراً ملتهبة متأججة."},{"id":"2127","jozz":"15","page":"292","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"4","line_end":"5","aya_no":"98","aya_text":"ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمۡ كَفَرُواْ بِـَٔايَٰتِنَا وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدًا","aya_text_emlaey":"ذلك جزاؤهم بأنهم كفروا بآياتنا وقالوا أئذا كنا عظاما ورفاتا أئنا لمبعوثون خلقا جديدا","aya_tafseer":"[98] هذا الذي وُصِف من العذاب عقاب للمشركين؛ بسبب كفرهم بآيات الله وحججه، وتكذيبهم رسله الذين دَعَوْهم إلى عبادته، وقولهم استنكاراً -إذا أُمروا بالتصديق بالبعث-: أإذا متنا وصِرْنا عظاماً بالية وأجزاءً متفتتة نُبعث بعد ذلك خَلْقاً جديداً؟"},{"id":"2128","jozz":"15","page":"292","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"5","line_end":"7","aya_no":"99","aya_text":"۞ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ قَادِرٌ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۡ وَجَعَلَ لَهُمۡ أَجَلٗا لَّا رَيۡبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورٗا","aya_text_emlaey":"أو لم يروا أن الله الذي خلق السموات والأرض قادر على أن يخلق مثلهم وجعل لهم أجلا لا ريب فيه فأبى الظالمون إلا كفورا","aya_tafseer":"[99] أَغَفَل هؤلاء المشركون، فلم يتبصروا ويعلموا أن الله الذي خلق السموات والأرض وما فيهن من المخلوقات على غير مثال سابق، قادر على أن يخلق أمثالهم بعد فنائهم؟ وقد جعل الله لهؤلاء المشركين وقتاً محدداً لموتهم وعذابهم، لا شك أنه آتيهم، ومع وضوح الحق ودلائله أبى الكافرون إلا جحوداً لدين الله عزَّ وجلَّ."},{"id":"2129","jozz":"15","page":"292","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"8","line_end":"9","aya_no":"100","aya_text":"قُل لَّوۡ أَنتُمۡ تَمۡلِكُونَ خَزَآئِنَ رَحۡمَةِ رَبِّيٓ إِذٗا لَّأَمۡسَكۡتُمۡ خَشۡيَةَ ٱلۡإِنفَاقِۚ وَكَانَ ٱلۡإِنسَٰنُ قَتُورٗا","aya_text_emlaey":"قل لو أنتم تملكون خزائن رحمة ربي إذا لأمسكتم خشية الإنفاق وكان الإنسان قتورا","aya_tafseer":"[100] قل -أيها الرسول- لهؤلاء المشركين: لو كنتم تملكون خزائن رحمة ربي التي لا تنفَدُ ولا تبيد إذاً لبخلتم بها، فلم تعطوا منها غيركم خوفاً مِن نفادها فتصبحوا فقراء. ومن شأن الإنسان أنه بخيل بما في يده إلا مَن عصم الله بالإيمان."},{"id":"2130","jozz":"15","page":"292","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"9","line_end":"11","aya_no":"101","aya_text":"وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ تِسۡعَ ءَايَٰتِۭ بَيِّنَٰتٖۖ فَسۡـَٔلۡ بَنِيٓ إِسۡرَٰٓءِيلَ إِذۡ جَآءَهُمۡ فَقَالَ لَهُۥ فِرۡعَوۡنُ إِنِّي لَأَظُنُّكَ يَٰمُوسَىٰ مَسۡحُورٗا","aya_text_emlaey":"ولقد آتينا موسى تسع آيات بينات فاسأل بني إسرائيل إذ جاءهم فقال له فرعون إني لأظنك ياموسى مسحورا","aya_tafseer":"[101] ولقد آتينا موسى تسع معجزات واضحات شاهدات على صِدْق نبوته وهي: العصا واليد والسنون ونقص الثمرات والطوفان والجراد والقمل والضفادع والدم، فاسأل -أيها الرسول- اليهود سؤال تقرير حين جاء موسى أسلافَهم بمعجزاته الواضحات، فقال فرعون لموسى: إني لأظنك -يا موسى- ساحراً، مخدوعاً مغلوباً على عقلك بما تأتيه مِن غرائب الأفعال."},{"id":"2131","jozz":"15","page":"292","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"11","line_end":"13","aya_no":"102","aya_text":"قَالَ لَقَدۡ عَلِمۡتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ بَصَآئِرَ وَإِنِّي لَأَظُنُّكَ يَٰفِرۡعَوۡنُ مَثۡبُورٗا","aya_text_emlaey":"قال لقد علمت ما أنـزل هؤلاء إلا رب السموات والأرض بصائر وإني لأظنك يافرعون مثبورا","aya_tafseer":"[102] فردَّ عليه موسى: لقد تيقَّنتَ -يا فرعون- أنه ما أنزل تلك المعجزات التسع الشاهدة على صدق نبوتي إلا رب السموات والأرض؛ لتكون دلالات يَستدِل بها أولو البصائر على وحدانية الله تعالى في ربوبيته وألوهيته، وإني لعلى يقين أنك -يا فرعون- هالك ملعون مغلوب."},{"id":"2132","jozz":"15","page":"292","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"13","line_end":"14","aya_no":"103","aya_text":"فَأَرَادَ أَن يَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ فَأَغۡرَقۡنَٰهُ وَمَن مَّعَهُۥ جَمِيعٗا","aya_text_emlaey":"فأراد أن يستفزهم من الأرض فأغرقناه ومن معه جميعا","aya_tafseer":"[103] فأراد فرعون أن يزعج موسى ويخرجه مع بني إسرائيل مِن أرض «مصر»، فأغرقناه ومَن معه مِن جندٍ في البحر عقاباً لهم."},{"id":"2133","jozz":"15","page":"292","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"14","line_end":"15","aya_no":"104","aya_text":"وَقُلۡنَا مِنۢ بَعۡدِهِۦ لِبَنِيٓ إِسۡرَٰٓءِيلَ ٱسۡكُنُواْ ٱلۡأَرۡضَ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ جِئۡنَا بِكُمۡ لَفِيفٗا","aya_text_emlaey":"وقلنا من بعده لبني إسرائيل اسكنوا الأرض فإذا جاء وعد الآخرة جئنا بكم لفيفا","aya_tafseer":"[104] وقلنا من بعد هلاك فرعون وجنده لبني إسرائيل: اسكنوا أرض «الشام»، فإذا جاء يوم القيامة جئنا بكم جميعاً مِن قبوركم إلى موقف الحساب."},{"id":"2134","jozz":"15","page":"293","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"1","line_end":"1","aya_no":"105","aya_text":"وَبِٱلۡحَقِّ أَنزَلۡنَٰهُ وَبِٱلۡحَقِّ نَزَلَۗ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرٗا وَنَذِيرٗا","aya_text_emlaey":"وبالحق أنـزلناه وبالحق نـزل وما أرسلناك إلا مبشرا ونذيرا","aya_tafseer":"[105] وبالحق أنزلنا هذا القرآن على محمد -صلى الله عليه وسلم- لأمْرِ العباد ونهيهم وثوابهم وعقابهم، وبالصدق والعدل والحفظ من التغيير والتبديل نزل. وما أرسلناك -أيها الرسول- إلا مبشراً بالجنة لمن أطاع، ومخوفاً بالنار لمن عصى وكفر."},{"id":"2135","jozz":"15","page":"293","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"2","line_end":"2","aya_no":"106","aya_text":"وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ وَنَزَّلۡنَٰهُ تَنزِيلٗا","aya_text_emlaey":"وقرآنا فرقناه لتقرأه على الناس على مكث ونـزلناه تنـزيلا","aya_tafseer":"[106] وأنزلنا إليك -أيها الرسول- قرآناً بيَّناه وأحكمناه وفَصَّلناه فارقاً بين الهدى والضلال والحق والباطل؛ لتقرأه على الناس في تؤدة وتمهُّل، ونَزَّلْناه مفرَّقاً، شيئاً بعد شيء، على حسب الحوادث ومقتضيات الأحوال."},{"id":"2136","jozz":"15","page":"293","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"3","line_end":"4","aya_no":"107","aya_text":"قُلۡ ءَامِنُواْ بِهِۦٓ أَوۡ لَا تُؤۡمِنُوٓاْۚ إِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدٗاۤ","aya_text_emlaey":"قل آمنوا به أو لا تؤمنوا إن الذين أوتوا العلم من قبله إذا يتلى عليهم يخرون للأذقان سجدا","aya_tafseer":"[107] قل -أيها الرسول- لهؤلاء المكذبين: آمِنوا بالقرآن أو لا تؤمنوا؛ فإن إيمانكم لا يزيده كمالاً، وتكذيبكم لا يُلْحِق به نقصاً. إن العلماء الذين أوتوا الكتب السابقة مِن قبل القرآن، وعرفوا حقيقة الوحي، إذا قرئ عليهم القرآن يخشعون، فيسجدون على وجوههم تعظيماً لله تعالى، وشكراً له."},{"id":"2137","jozz":"15","page":"293","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"4","line_end":"5","aya_no":"108","aya_text":"وَيَقُولُونَ سُبۡحَٰنَ رَبِّنَآ إِن كَانَ وَعۡدُ رَبِّنَا لَمَفۡعُولٗا","aya_text_emlaey":"ويقولون سبحان ربنا إن كان وعد ربنا لمفعولا","aya_tafseer":"[108] ويقول هؤلاء الذين أوتوا العلم عند سماع القرآن: تنزيهاً لربنا وتبرئة له مما يصفه المشركون به، ما كان وعد الله تعالى من ثواب وعقاب إلا واقعاً حقّاً."},{"id":"2138","jozz":"15","page":"293","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"5","line_end":"6","aya_no":"109","aya_text":"وَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ خُشُوعٗا۩","aya_text_emlaey":"ويخرون للأذقان يبكون ويزيدهم خشوعا","aya_tafseer":"[109] ويقع هؤلاء ساجدين على وجوههم، يبكون تأثراً بمواعظ القرآن، ويزيدهم سماع القرآن ومواعظه خضوعاً لأمر الله وعظيم قدرته."},{"id":"2139","jozz":"15","page":"293","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"6","line_end":"8","aya_no":"110","aya_text":"قُلِ ٱدۡعُواْ ٱللَّهَ أَوِ ٱدۡعُواْ ٱلرَّحۡمَٰنَۖ أَيّٗا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَيۡنَ ذَٰلِكَ سَبِيلٗا","aya_text_emlaey":"قل ادعوا الله أو ادعوا الرحمن أيا ما تدعوا فله الأسماء الحسنى ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا","aya_tafseer":"[110] قل -أيها الرسول- لمشركي قومك الذين أنكروا عليك الدعاء بقولك: يا ألله يا رحمن، ادعوا الله، أو ادعوا الرحمن، فبأي أسمائه دعوتموه فإنكم تدعون ربّاً واحداً؛ لأن أسماءه كلها حسنى. ولا تجهر بالقراءة في صلاتك، فيسمعك المشركون، ولا تُسِرَّ بها فلا يسمعك أصحابك، وكن وسطاً بين الجهر والهمس."},{"id":"2140","jozz":"15","page":"293","sura_no":"17","sura_name_en":"Al-Isrā’","sura_name_ar":"الإسرَاء ","line_start":"8","line_end":"9","aya_no":"111","aya_text":"وَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَلَمۡ يَكُن لَّهُۥ وَلِيّٞ مِّنَ ٱلذُّلِّۖ وَكَبِّرۡهُ تَكۡبِيرَۢا","aya_text_emlaey":"وقل الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا","aya_tafseer":"[111] وقل -أيها الرسول-: الحمد لله الذي له الكمال والثناء، الذي تنزَّه عن الولد والشريك في ألوهيته، ولا يكون له سبحانه وليٌّ مِن خلقه فهو الغني القوي، وهم الفقراء المحتاجون إليه، وعظِّمه تعظيماً تامّاً بالثناء عليه وعبادته وحده لا شريك له، وإخلاص الدين كله له."}]
